import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long rem = 1L << 32;
        long res_a = 1L << 32;
        long res_b = 1L << 32;

        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        for (long b = 1; b <= n; b++) {
            long a = Math.max(x * b / y - 10, 0);
            for (int j = 0; j < 20; j++) {
                long diff = Math.abs(x * b - (a + j) * y);
                if (rem * b > diff * res_b) {
                    rem = diff;
                    res_a = a + j;
                    res_b = b;
                } else if (rem * b == diff * res_b) {
                    if (res_b > b || (res_b == b && res_a > a + j)) {
                        rem = diff;
                        res_a = a + j;
                        res_b = b;
                    }
                }
            }
        }
        System.out.println(res_a + "/" + res_b);
        scanner.close();
    }
}
